sys_script_include.script:
(function transform(transformBuilder, transformScriptArgs) {
    try {
        if(!transformBuilder) return;
        var listModel = transformBuilder

        .transform();

        // Loop through rows and update empty comment cells
        listModel.rowDefinitions.rows.forEach(function(row) {
            var commentCell = row.cells['comments']; // Replace with your field name

            if (commentCell && (!commentCell.value || commentCell.value.trim() === '')) {
                commentCell.value = '+ Add comment';
            }
        });

        return listModel;
    }
    catch(error) {
        return {
            failed: true,
            error: error.message
        };
    }
})(transformBuilder, transformScriptArgs);
